import re

root = pathlib.Path(__file__).parent
out = []

tests_dir = root / "tests"
out.append("TESTS_DIR_EXISTS=%s" % tests_dir.exists())
for p in sorted(root.glob("**/*")):
    if p.is_file() and "site-packages" not in str(p):
        out.append(f"FILE: {p.relative_to(root)}")

if tests_dir.exists():
    pat = re.compile(r"ud_match|defnoun|defverb|defadj|user_defined")
    for p in sorted(tests_dir.glob("**/*.py")):
        lines = p.read_text().splitlines()
        hits = [i for i, line in enumerate(lines) if pat.search(line)]
        if hits:
            out.append(f"=== {p.relative_to(root)} hits={hits[:40]}")
            for i in hits[:20]:
                out.append("\n".join(f"{j+1}: {lines[j]}" for j in range(max(0, i - 1), min(len(lines), i + 4))))
                out.append("---")

(root / "_dump_d.txt").write_text("\n".join(out))

